export type Row<T> = { at: number; rank: number; line: T }

/** The `budget` rows that matter most, back in their places; a tie goes to the row given first. */
export function pickRows<T>(rows: Row<T>[], budget: number): Row<T>[] {
  return rows
    .map((row, index) => ({ row, index }))
    .sort((a, b) => a.row.rank - b.row.rank || a.index - b.index)
    .slice(0, Math.max(0, budget))
    .map(({ row }) => row)
    .sort((a, b) => a.at - b.at)
