export type PlanLine = { kind: 'phase'; phase: PlanPhase } | { kind: 'task'; phase: PlanPhase; task: PlanTask }

/** Ranks the plan's rows share with the pane's others: the session's first lines sit at 3. */
export const PLAN_RANK = { live: 1, open: 2, phase: 4, livePhase: 5, laterOpen: 6, settled: 7 } as const

const isSettled = (task: PlanTask) => task.status === 'done' || task.status === 'dropped'

/**
 * The plan's rows from `at` on, ranked: the live task and its phase's line,
 * then the first open phase and its tasks, then the other phases' lines, the
 * live phase's other tasks, the later open phases' tasks and the settled rest.
 */
export function planRows(plan: PlanPhase[], liveTask: string | null, at: number): Row<PlanLine>[] {
  const isOpen = (phase: PlanPhase) => phase.status !== 'done' && phase.status !== 'dropped'
  const open = plan.find(phase => isOpen(phase) && phase.tasks.some(task => !isSettled(task)))
  const live = plan.find(phase => phase.tasks.some(task => task.id === liveTask))
  const rows: Row<PlanLine>[] = []
  plan.forEach((phase, p) => {
    const phaseRank = phase === live ? PLAN_RANK.live : phase === open ? PLAN_RANK.open - 0.5 : PLAN_RANK.phase
    rows.push({ at: at + rows.length, rank: phaseRank, line: { kind: 'phase', phase } })
    phase.tasks.forEach((task, t) => {
      const rank =
        task.id === liveTask
          ? PLAN_RANK.live
          : phase === open
            ? PLAN_RANK.open + t / 1000
            : phase === live
              ? PLAN_RANK.livePhase + t / 1000
              : isOpen(phase)
                ? PLAN_RANK.laterOpen + p / 100 + t / 10000
                : PLAN_RANK.settled
      rows.push({ at: at + rows.length, rank, line: { kind: 'task', phase, task } })
    })
  })
  return rows
}
